263	    /**
264	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
265	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
266	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
267	     * a known region (see {@link Region}), the postcode must fall within that region's range
268	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
269	     * postcode.
270	     *
271	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
272	     */
273	    private void assertPostcodeValid(Owner owner) {
274	        String postcode = owner.getPostcode();
275	        if (postcode == null) {
276	            return;
277	        }
278	        String region = Region.forCity(owner.getCity());
279	        int[] range = region == null ? null : Region.postcodeRange(region);
280	        if (range == null) {
281	            return;
282	        }
283	        int value = Integer.parseInt(postcode);
284	        if (value < range[0] || value > range[1]) {
285	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
286	        }
287	    }
288	
289	    /**
290	     * Rejects saving {@code owner} when it carries a {@code registrationDate} later than the current
291	     * server date. The registration date is optional: a {@code null} date is left untouched (it is
292	     * defaulted to today by {@link #saveOwner(Owner)}). A registration cannot be dated in the future.
293	     *
294	     * @throws FutureRegistrationDateException if the supplied registration date is after today
295	     */
296	    private void assertRegistrationDateNotFuture(Owner owner) {
297	        LocalDate registrationDate = owner.getRegistrationDate();
298	        if (registrationDate == null) {
299	            return;
300	        }
301	        LocalDate today = LocalDate.now();
302	        if (registrationDate.isAfter(today)) {
303	            throw new FutureRegistrationDateException(registrationDate, today);
304	        }
305	    }
