334	    @Override
335	    @Transactional
336	    public void saveOwner(Owner owner) throws DataAccessException {
337	        assertPostcodeValid(owner);
338	        assertRegistrationDateNotFuture(owner);
339	        if (owner.getTelephone() != null) {
340	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
341	        }
342	        if (owner.getEmail() != null) {
343	            owner.setEmail(normalizeEmail(owner.getEmail()));
344	        }
345	        assertEmailDomainAllowed(owner);
346	        applyAddress(owner);
347	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
348	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
349	        if (owner.getCustomerCode() == null) {
350	            owner.setCustomerCode(generateCustomerCode(owner));
351	        }
352	        boolean creating = owner.isNew();
353	        if (creating) {
354	            owner.setNamesakeCount(countNamesakes(owner));
355	            assertDailyCapacity(owner);
356	            assertCityCapacity(owner);
357	        }
358	        assignHouseholdId(owner);
359	        assertIdentityUnique(owner);
360	        applySoftMatch(owner);
361	        if (creating) {
362	            applyMembershipLevelCap(owner);
363	        }
364	        ownerRepository.save(owner);
365	        populateHouseholdSize(owner);
366	        if (creating) {
367	            AUDIT.info(
368	                "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
369	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
370	                owner.getMembershipLevel(), owner.getMembershipNumber());
371	            AUDIT.info(ownerCreatedEvent(owner));
372	        }
373	    }
374	
375	    /**
376	     * Builds the immutable structured {@code OWNER_CREATED} audit event as a compact JSON object
377	     * {@code {seq, ownerId, customerCode, membershipLevel, event}}. The {@code seq} is a
378	     * process-wide, monotonically increasing integer stamped once per created owner.
379	     *
380	     * <p>The identifier field carries the owner's <em>current primary identifier</em>, sourced
381	     * through {@link #primaryIdentifier(Owner)}; today that is the {@code customerCode}. When the
382	     * primary identifier is later unified into the {@code memberId}, that single helper changes and
383	     * the event automatically carries the new identifier.
384	     */
385	    private String ownerCreatedEvent(Owner owner) {
386	        Map<String, Object> event = new LinkedHashMap<>();
387	        event.put("seq", OWNER_CREATED_SEQ.incrementAndGet());
388	        event.put("ownerId", owner.getId());
389	        event.put("customerCode", primaryIdentifier(owner));
390	        event.put("membershipLevel", owner.getMembershipLevel());
391	        event.put("event", "OWNER_CREATED");
392	        return AUDIT_MAPPER.writeValueAsString(event);
393	    }
394	
395	    /**
396	     * The owner's current primary identifier. Today this is the {@code customerCode}; when the
397	     * customerCode is later unified into the {@code memberId}, this is the single place to switch
398	     * so every consumer (notably the structured audit event) follows.
399	     */
400	    private String primaryIdentifier(Owner owner) {
401	        return owner.getCustomerCode();
402	    }
403	
404	    /**
405	     * Build a {@code customerCode} formatted {@code '<REGION>-<HASH8>'} where REGION is the region
406	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}) and
407	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
408	     * the owner's normalized telephone and {@code lastName}. The telephone is already normalized by
409	     * {@link #saveOwner(Owner)} before this runs. The {@code '<REGION>-<HASH8>'} layout is read back
410	     * by {@link Region#regionOfCustomerCode(String)}; keep the two in sync.
411	     */
412	    private String generateCustomerCode(Owner owner) {
413	        String region = Region.regionForPostcode(owner.getPostcode());
414	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
415	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
416	        String hash8 = Sha256Hex.upperHex(telephone + lastName, 8);
417	        return deduplicateCustomerCode(owner, region + "-" + hash8);
418	    }
419	
420	    /**
421	     * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
422	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
423	     * existing owners' {@code customerCode}s. The {@code owner} being saved is excluded from the
424	     * comparison so re-saving it does not treat its own code as a collision.
425	     */
426	    private String deduplicateCustomerCode(Owner owner, String base) {
427	        Set<String> taken = new HashSet<>();
428	        for (Owner existing : ownerRepository.findAll()) {
429	            if (!existing.getId().equals(owner.getId()) && existing.getCustomerCode() != null) {
430	                taken.add(existing.getCustomerCode());
431	            }
432	        }
433	        if (!taken.contains(base)) {
434	            return base;
435	        }
436	        int n = 2;
437	        while (taken.contains(base + "-" + n)) {
438	            n++;
439	        }
440	        return base + "-" + n;
441	    }
