443	    /** Maximum number of owners permitted in a single city. */
444	    private static final long CITY_OWNER_LIMIT = 50L;
445	
446	    /** A city with at least this many owners (but below {@link #CITY_OWNER_LIMIT}) raises the
447	     *  approaching-capacity warning. */
448	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
449	
450	    /**
451	     * Reports whether {@code city} is approaching the per-city capacity limit, i.e. it already holds
452	     * between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@code CITY_OWNER_LIMIT - 1} owners
453	     * (inclusive), reusing the same per-city count as the hard limit ({@link #assertCityCapacity}).
454	     */
455	    @Override
456	    @Transactional(readOnly = true)
457	    public boolean isCityCapacityWarningActive(String city) throws DataAccessException {
458	        if (city == null) {
459	            return false;
460	        }
461	        long count = countOwnersInCity(city);
462	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
463	    }
464	
465	    /**
466	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
467	     * more owners, so no city can grow beyond the capacity limit.
468	     *
469	     * @throws CityOwnerLimitException if the owner's city is already at capacity
470	     */
471	    private void assertCityCapacity(Owner owner) {
472	        if (owner.getCity() == null) {
473	            return;
474	        }
475	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
476	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
477	        }
478	    }
479	
480	    /** Fixed public holidays that the business-day roll skips. */
481	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
482	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
483	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
484	            LocalDate.parse("2026-12-28"));
485	
486	    /**
487	     * Rolls {@code date} forward to the next business day. A business day is Monday to Friday that is
488	     * not a listed public holiday; Saturdays, Sundays and public holidays are skipped by advancing
489	     * one day at a time until a business day is reached. Business days are returned unchanged.
490	     */
491	    private static LocalDate rollToBusinessDay(LocalDate date) {
492	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
493	            date = date.plusDays(1);
494	        }
495	        return date;
496	    }
497	
498	    private static boolean isWeekend(LocalDate date) {
499	        switch (date.getDayOfWeek()) {
500	            case SATURDAY:
501	            case SUNDAY:
502	                return true;
503	            default:
504	                return false;
505	        }
506	    }
507	
508	    /** Maximum number of owners permitted to be registered on a single day. */
509	    private static final long DAILY_OWNER_LIMIT = 100L;
510	
511	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
512	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
513	
514	    /**
515	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
516	     * today, reusing the same daily accumulation as the per-day create limit ({@link
517	     * #assertDailyCapacity}).
518	     */
519	    @Override
520	    @Transactional(readOnly = true)
521	    public boolean isBulkSignupWarningActive() throws DataAccessException {
522	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
523	    }
524	
525	    /**
526	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
527	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
528	     * many owners can be created on any single day.
529	     *
530	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
531	     */
532	    private void assertDailyCapacity(Owner owner) {
533	        LocalDate date = owner.getRegistrationDate();
534	        if (date == null) {
535	            return;
536	        }
537	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
538	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
539	        }
540	    }
541	
542	    private long countOwnersRegisteredOn(LocalDate date) {
543	        return ownerRepository.findAll().stream()
544	                .filter(existing -> date.equals(existing.getRegistrationDate()))
545	                .count();
546	    }
547	
548	    private long countOwnersInCity(String city) {
549	        String normalized = normalizeHouseholdValue(city);
550	        return ownerRepository.findAll().stream()
551	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
552	                .count();
553	    }
554	
555	    /**
556	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
557	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
558	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
559	     * that already existed before this create.
560	     */
561	    private int countNamesakes(Owner owner) {
562	        String firstName = normalizeHouseholdValue(owner.getFirstName());
563	        String lastName = normalizeHouseholdValue(owner.getLastName());
564	        int count = 0;
565	        for (Owner existing : ownerRepository.findAll()) {
566	            if (!existing.getId().equals(owner.getId())
567	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
568	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
569	                count++;
570	            }
571	        }
572	        return count;
573	    }
574	
575	    private static String normalizeEmail(String email) {
576	        return email == null ? null : email.toLowerCase(Locale.ROOT);
577	    }
578	
579	    /**
580	     * Normalizes whichever address fields {@code owner} supplied and derives the effective flat
581	     * {@code address} from them. The structured form is preferred: when a non-blank
582	     * {@code addressLine1} is present, {@code address} is set to the normalized {@code addressLine1},
583	     * with a single space and the normalized {@code addressLine2} appended when {@code addressLine2}
584	     * is present. Otherwise the flat {@code address} is normalized in place (backward-compatible). The
585	     * structured fields are also stored in their normalized form. Because everything downstream reads
586	     * {@link Owner#getAddress()}, the household hash, postcode validation and locality all see the
587	     * structured value when present and fall back to the flat address otherwise.
588	     */
589	    private static void applyAddress(Owner owner) {
590	        String line1 = normalizeAddress(owner.getAddressLine1());
591	        String line2 = normalizeAddress(owner.getAddressLine2());
592	        owner.setAddressLine1(line1);
593	        owner.setAddressLine2(line2);
594	        if (line1 != null && !line1.isEmpty()) {
595	            String composed = (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
596	            owner.setAddress(composed);
597	        } else if (owner.getAddress() != null) {
598	            owner.setAddress(normalizeAddress(owner.getAddress()));
599	        }
600	    }
601	
602	    /** Common street-type abbreviations expanded during address normalization. */
603	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
604	        "ST", "STREET",
605	        "RD", "ROAD",
606	        "AVE", "AVENUE");
607	
608	    /**
609	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
610	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
611	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
612	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
613	     * form.
614	     */
615	    private static String normalizeAddress(String address) {
616	        if (address == null) {
617	            return null;
618	        }
619	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
620	        if (collapsed.isEmpty()) {
621	            return "";
622	        }
623	        String[] tokens = collapsed.split(" ");
624	        StringBuilder sb = new StringBuilder(collapsed.length());
625	        for (int i = 0; i < tokens.length; i++) {
626	            if (i > 0) {
627	                sb.append(' ');
628	            }
629	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
630	        }
631	        return sb.toString();
632	    }
633	
634	    private static String normalizeTelephone(String telephone) {
635	        return telephone == null ? null : E164Telephone.toE164(telephone);
636	    }
637	
638	    /**
639	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
640	     * that of another non-deleted owner. The key is the SHA-256 hex over the normalized telephone,
641	     * lower-cased email and {@code soundex(lastName)}, so it consolidates the former separate
642	     * telephone, email and household duplicate rules into a single check — only an exact full-key
643	     * match is a hard duplicate. Owners flagged {@link Owner#isDeleted() deleted} are ignored.
644	     *
645	     * @throws DuplicateIdentityException if another owner already has the same identity key
646	     */
647	    private void assertIdentityUnique(Owner owner) {
648	        String identityKey = owner.getIdentityKey();
649	        for (Owner existing : ownerRepository.findAll()) {
650	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
651	                    && identityKey.equals(existing.getIdentityKey())) {
652	                throw new DuplicateIdentityException(identityKey);
653	            }
654	        }
655	    }
656	
657	    /**
658	     * Flags {@code owner} as a soft match ({@link Owner#isPossibleDuplicate()} /
659	     * {@link Owner#getPossibleDuplicateOf()}) when its {@link Owner#getIdentityKey() identity key}
660	     * differs from every existing owner's (so it is not a hard duplicate) yet it shares an existing,
661	     * non-deleted owner's {@code soundex(lastName)} and {@code postcode}. This is what now admits two
662	     * owners with the same {@code lastName} and {@code postcode} but different telephones: they are
663	     * created as a soft match rather than rejected. The first matching owner (by store iteration
664	     * order) is recorded. Any prior flag is cleared first, and no match is possible when the owner
665	     * has no postcode or a last name that yields an empty soundex.
666	     */
667	    private void applySoftMatch(Owner owner) {
668	        owner.setPossibleDuplicate(false);
669	        owner.setPossibleDuplicateOf(null);
670	        String soundex = Soundex.encode(owner.getLastName());
671	        String postcode = owner.getPostcode();
672	        if (soundex.isEmpty() || postcode == null || postcode.isBlank()) {
673	            return;
674	        }
675	        String identityKey = owner.getIdentityKey();
676	        for (Owner existing : ownerRepository.findAll()) {
677	            if (existing.getId().equals(owner.getId()) || existing.isDeleted()) {
678	                continue;
679	            }
680	            if (!identityKey.equals(existing.getIdentityKey())
681	                    && soundex.equals(Soundex.encode(existing.getLastName()))
682	                    && postcode.equals(existing.getPostcode())) {
683	                owner.setPossibleDuplicate(true);
684	                owner.setPossibleDuplicateOf(existing.getId());
685	                return;
686	            }
687	        }
688	    }
689	
690	    /**
691	     * Assigns {@code owner} its deterministic {@code householdId}: the first 12 upper-case hex
692	     * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}, so all
693	     * owners that share a normalized {@code lastName} and {@code postcode} automatically share the
694	     * same household. Left {@code null} when either the lastName or the postcode is absent, since a
695	     * household is keyed on both.
696	     */
697	    private void assignHouseholdId(Owner owner) {
698	        String lastName = normalizeHouseholdValue(owner.getLastName());
699	        String postcode = owner.getPostcode();
700	        if (lastName.isEmpty() || postcode == null || postcode.isBlank()) {
701	            owner.setHouseholdId(null);
702	            return;
703	        }
704	        owner.setHouseholdId(generateHouseholdId(lastName, postcode));
705	    }
706	
707	    /**
708	     * Captures the membership-level ceiling for a newly created {@code owner}: its
709	     * {@link Owner#getMembershipLevel() membership level} may not exceed one above the highest level
710	     * among the household members (owners sharing its {@code householdId}) that already exist. When
711	     * the owner belongs to no household, or no existing member shares it, no cap applies and the
712	     * level is left uncapped. Each existing member's household size is stamped via
713	     * {@link #populateHouseholdSizes(Collection)} first so its level reflects the household-size
714	     * membership points.
715	     *
716	     * @see Owner#getMembershipLevelCap()
717	     */
718	    private void applyMembershipLevelCap(Owner owner) {
719	        owner.setMembershipLevelCap(null);
720	        String householdId = owner.getHouseholdId();
721	        if (householdId == null || householdId.isBlank()) {
722	            return;
723	        }
724	        List<Owner> members = new ArrayList<>();
725	        for (Owner existing : ownerRepository.findAll()) {
726	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
727	                    && householdId.equals(existing.getHouseholdId())) {
728	                members.add(existing);
729	            }
730	        }
731	        if (members.isEmpty()) {
732	            return;
733	        }
734	        populateHouseholdSizes(members);
735	        int maxLevel = 0;
736	        for (Owner member : members) {
737	            maxLevel = Math.max(maxLevel, member.getMembershipLevel());
738	        }
739	        owner.setMembershipLevelCap(maxLevel + 1);
740	    }
741	
742	    /**
743	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
744	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
745	     * reaching into the data store. A {@code null} owner or one without a household id is left at
746	     * size 0.
747	     */
748	    private void populateHouseholdSize(Owner owner) {
749	        if (owner == null) {
750	            return;
751	        }
752	        String householdId = owner.getHouseholdId();
753	        if (householdId == null || householdId.isBlank()) {
754	            owner.setHouseholdSize(0);
755	            return;
756	        }
757	        int count = 0;
758	        for (Owner existing : ownerRepository.findAll()) {
759	            if (householdId.equals(existing.getHouseholdId())) {
760	                count++;
761	            }
762	        }
763	        owner.setHouseholdSize(count);
764	    }
765	
766	    /**
767	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
768	     * store, so a list/page of owners is counted without a per-owner query.
769	     *
770	     * @see #populateHouseholdSize(Owner)
771	     */
772	    private void populateHouseholdSizes(Collection<Owner> owners) {
773	        if (owners.isEmpty()) {
774	            return;
775	        }
776	        Map<String, Integer> sizes = new HashMap<>();
777	        for (Owner existing : ownerRepository.findAll()) {
778	            String householdId = existing.getHouseholdId();
779	            if (householdId != null && !householdId.isBlank()) {
780	                sizes.merge(householdId, 1, Integer::sum);
781	            }
782	        }
783	        for (Owner owner : owners) {
784	            String householdId = owner.getHouseholdId();
785	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
786	        }
787	    }
788	
789	    /**
790	     * Derives the deterministic {@code householdId} from the normalized {@code lastName} and
791	     * {@code postcode}: the first 12 upper-case hex characters of SHA-256 over
792	     * {@code lastName + '|' + postcode}, so all owners in the same household share the same
793	     * identifier.
794	     */
795	    private static String generateHouseholdId(String lastName, String postcode) {
796	        return Sha256Hex.upperHex(lastName + "|" + postcode, 12);
797	    }
798	
799	    /**
800	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
801	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
802	     */
803	    private static String normalizeHouseholdValue(String value) {
804	        if (value == null) {
805	            return "";
806	        }
807	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
808	    }
809	
810	    @Override
811	    @Transactional(readOnly = true)
812	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
813	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
814	        populateHouseholdSizes(owners);
815	        return owners;
816	    }
817	
818	    @Override
819	    @Transactional(readOnly = true)
820	    public Collection<Visit> findVisitsByPetId(int petId) {
821	        return visitRepository.findByPetId(petId);
822	    }
823	
824	    @Override
825	    @Transactional(readOnly = true)
826	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
827	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
828	    }
829	
830	    private <T> T findEntityById(Supplier<T> supplier) {
831	        try {
832	            return supplier.get();
833	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
834	            // Just ignore not found exceptions for Jdbc/Jpa realization
835	            return null;
836	        }
837	    }
838	
839	}
