private static int luhnCheckDigit(String value) {
    int sum = 0;
    boolean dbl = true;
    for (int i = value.length() - 1; i >= 0; i--) {
        char c = value.charAt(i);
        if (c < '0' || c > '9') {
            continue;
        }
        int d = c - '0';
        if (dbl) {
            d *= 2;
            if (d > 9) {
                d -= 9;
            }
        }
        sum += d;
        dbl = !dbl;
    }
    return (10 - (sum % 10)) % 10;
}

